style.css:
/* i really want this to be global */
/* Deluge WebUI 2.x - Dark Theme
 * Tema oscuro para Deluge WebUI (ExtJS 3, tema "gray").
 *
 * Stylish: pega este CSS tal cual y en "Aplicar a" elige
 * "URLs que empiezan por" http://192.168.1.189:8112/
 *
 * Los colores se cambian en el bloque :root de abajo.
 */
/* =========================================================
   PALETA - cambia aqui los colores
   ========================================================= */
:root {
  --bg:        #16181d;   /* fondo general */
  --bg2:       #1d2026;   /* cuerpo de paneles / grid */
  --bg3:       #252930;   /* cabeceras, toolbars */
  --bg4:       #2f343d;   /* hover */
  --bg-input:  #12141a;
  --border:    #343a44;
  --border2:   #444b57;
  --text:      #d8dbe1;
  --text-dim:  #8f96a3;
  --accent:    #599eee;   /* azul Deluge */
  --sel:       rgba(89,158,238,.22);
  --sel-bd:    rgba(89,158,238,.55);

  --p-down:    #3b82d6;   /* barra de progreso */
  --p-error:   #d64545;   /* errores / campos invalidos */

  color-scheme: dark;
  accent-color: var(--accent);
}

/* =========================================================
   BASE
   ========================================================= */
html, body,
.x-viewport, .x-viewport body {
  background: var(--bg) !important;
  color: var(--text) !important;
}
body, .x-panel, .x-form-item, .x-form-item label,
.x-panel-body, .x-window-body, .x-plain-body, .x-box-inner,
.x-form-display-field, .ext-mb-text, .x-tree-node, .x-list-body,
.x-grid3-cell-inner, .x-grid3-hd-inner, .x-toolbar, .xtb-text,
.x-fieldset, .x-form-cb-label {
  color: var(--text) !important;
}
::selection { background: var(--sel-bd); color: #fff; }

/* Scrollbars */
* { scrollbar-color: var(--border2) var(--bg2); scrollbar-width: thin; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: var(--bg2); }
::-webkit-scrollbar-thumb { background: var(--border2); border-radius: 6px; border: 2px solid var(--bg2); }
::-webkit-scrollbar-thumb:hover { background: #5a6270; }
::-webkit-scrollbar-corner { background: var(--bg2); }

/* =========================================================
   PANELES / LAYOUT
   ========================================================= */
.x-border-layout-ct,
.x-panel-body, .x-panel-bwrap,
.x-plain-body, .x-box-layout-ct {
  background: var(--bg2) !important;
  border-color: var(--border) !important;
}
#mainPanel > .x-panel-bwrap > .x-panel-body { background: var(--bg) !important; }

.x-panel-header,
.x-panel-header.x-accordion-hd,
.x-tab-panel-header {
  background: var(--bg3) !important;
  background-image: none !important;
  border-color: var(--border) !important;
  color: var(--text) !important;
}
.x-panel-header-text, .x-window-header-text, .x-panel-header span {
  color: var(--text) !important;
  font-weight: 600;
}
.x-accordion-hd { border-bottom: 1px solid var(--border) !important; }
.x-accordion-hd:hover { background: var(--bg4) !important; }

/* Splitters */
.x-layout-split, .x-splitbar-h, .x-splitbar-v { background: var(--bg) !important; }
.x-splitbar-proxy { background: var(--accent) !important; opacity: .5; }

/* Iconos de herramientas (colapsar, etc.) */
.x-tool { filter: invert(.8) brightness(1.3); opacity: .8; }
.x-tool:hover { opacity: 1; }

/* =========================================================
   TOOLBARS + BOTONES
   ========================================================= */
.x-toolbar, .x-panel-tbar .x-toolbar, .x-panel-bbar .x-toolbar,
.x-statusbar, .x-panel-fbar, .x-panel-btns, .x-window-footer {
  background: var(--bg3) !important;
  background-image: none !important;
  border-color: var(--border) !important;
}
.x-panel-tbar .x-toolbar { border-bottom: 1px solid var(--border) !important; }
#deluge-statusbar { border-top: 1px solid var(--border) !important; }

.xtb-sep {
  background-image: none !important;
  border-left: 1px solid var(--border2) !important;
  width: 0 !important; height: 16px !important; margin: 0 6px !important;
}

/* Quitar los sprites de los 9 trozos del boton */
.x-btn td.x-btn-tl, .x-btn td.x-btn-tc, .x-btn td.x-btn-tr,
.x-btn td.x-btn-ml, .x-btn td.x-btn-mc, .x-btn td.x-btn-mr,
.x-btn td.x-btn-bl, .x-btn td.x-btn-bc, .x-btn td.x-btn-br {
  background-image: none !important;
  background-color: transparent !important;
}
.x-btn { border-radius: 4px; transition: background-color .12s; }
.x-btn button, .x-btn-text { color: var(--text) !important; }

.x-btn-over, .x-btn-focus { background: var(--bg4) !important; }
.x-btn-click, .x-btn-pressed, .x-btn-menu-active {
  background: var(--sel) !important;
  box-shadow: inset 0 0 0 1px var(--sel-bd);
}
/* Botones de dialogo (OK, Cancel, Login...) */
.x-panel-btns .x-btn, .x-window-footer .x-btn, .x-panel-fbar .x-btn {
  background: var(--bg4) !important;
  box-shadow: inset 0 0 0 1px var(--border2);
}
.x-panel-btns .x-btn-over, .x-window-footer .x-btn-over, .x-panel-fbar .x-btn-over {
  background: var(--accent) !important;
}
.x-panel-btns .x-btn-over button, .x-window-footer .x-btn-over button { color: #fff !important; }

.x-item-disabled, .x-item-disabled * { color: var(--text-dim) !important; }

/* Flecha de los botones de la statusbar (sprite oscuro -> caret CSS) */
.x-btn .x-btn-arrow { background-image: none !important; position: relative; }
.x-btn .x-btn-arrow:after {
  content: ""; position: absolute; right: 1px; top: 50%; margin-top: -2px;
  border: 4px solid transparent; border-top-color: var(--text-dim);
}

/* deluge.css fuerza el boton "Deluge" a negro con !important */
#tbar-deluge-text button.x-btn-text { color: var(--text) !important; }

/* Statusbar */
.x-deluge-statusbar, #deluge-statusbar .x-btn-text { color: var(--text-dim) !important; }
#statusbar-externalip b { color: var(--accent); }

/* =========================================================
   GRID (lista de torrents, peers, connection manager...)
   ========================================================= */
.x-grid3, .x-grid3-viewport, .x-grid3-scroller, .x-grid3-body,
.x-grid-panel .x-panel-body {
  background: var(--bg2) !important;
  border-color: var(--border) !important;
}
.x-grid3-header {
  background: var(--bg3) !important;
  background-image: none !important;
  border-bottom: 1px solid var(--border) !important;
}
.x-grid3-hd-row td, td.x-grid3-hd {
  background: var(--bg3) !important;
  background-image: none !important;
  border-left-color: var(--border) !important;
  border-right-color: var(--border) !important;
}
.x-grid3-hd-inner { color: var(--text-dim) !important; font-weight: 600; }
td.x-grid3-hd-over, td.sort-asc, td.sort-desc, td.x-grid3-hd-menu-open {
  background: var(--bg4) !important;
}
td.x-grid3-hd-over .x-grid3-hd-inner,
td.sort-asc .x-grid3-hd-inner, td.sort-desc .x-grid3-hd-inner,
td.x-grid3-hd-menu-open .x-grid3-hd-inner,
.x-treegrid-hd-inner, .x-grid3-hd-inner {
  background-image: none !important;
  background-color: transparent !important;
}
td.x-grid3-hd-over .x-grid3-hd-inner,
td.sort-asc .x-grid3-hd-inner, td.sort-desc .x-grid3-hd-inner,
td.x-grid3-hd-menu-open .x-grid3-hd-inner { color: var(--text) !important; }
.x-grid3-hd-btn { background-color: var(--bg4) !important; filter: brightness(.8); }
.x-grid3-sort-icon { filter: invert(.7); }

.x-grid3-row {
  background: var(--bg2) !important;
  border-color: var(--bg2) !important;
  border-top-color: var(--bg2) !important;
}
.x-grid3-row-alt { background: #1a1d22 !important; }
.x-grid3-row td, .x-grid3-summary-row td { border-color: transparent !important; }
.x-grid3-row-over { background: var(--bg4) !important; background-image: none !important; }
.x-grid3-row-selected, .x-grid3-row-selected.x-grid3-row-over {
  background: var(--sel) !important;
  background-image: none !important;
  border-color: var(--sel-bd) !important;
}
.x-grid3-row-selected .x-grid3-cell-inner { color: #fff !important; }
.x-grid3-cell-selected { background: var(--sel) !important; }
.x-grid3-dirty-cell { background-image: none !important; }
.x-grid-empty { color: var(--text-dim) !important; }

.x-grid3-resize-proxy, .x-grid3-resize-marker { background: var(--accent) !important; }
.x-dd-drag-proxy, .x-dd-drag-ghost {
  background: var(--bg3) !important; color: var(--text) !important; border-color: var(--border2) !important;
}

/* =========================================================
   BARRAS DE PROGRESO
   ========================================================= */
.x-progress-wrap {
  border: 1px solid var(--border) !important;
  border-radius: 3px;
  overflow: hidden;
  background: var(--bg-input) !important;
}
.x-progress-inner { background: var(--bg-input) !important; background-image: none !important; }
.x-progress-bar {
  background: var(--p-down) !important;
  background-image: none !important;
  border: none !important;
}
.x-progress-text { color: #fff !important; }
.x-progress-text-back { color: var(--text) !important; }


/* =========================================================
   SIDEBAR / LISTVIEWS (filtros, preferencias, plugins)
   ========================================================= */
.x-list-wrap, .x-list-body, .x-list-body-inner { background: transparent !important; }
.x-list-header, .x-list-header-inner {
  background: var(--bg3) !important; background-image: none !important;
  border-color: var(--border) !important;
}
.x-list-body dl { border-radius: 3px; margin: 1px 4px; }
.x-list-body dl.x-list-over { background: var(--bg4) !important; }
.x-list-body dl.x-list-selected {
  background: var(--sel) !important;
  box-shadow: inset 2px 0 0 var(--accent);
}
.x-list-selected .x-deluge-filter, .x-list-selected em { color: #fff !important; }
.deluge-sidebar .x-panel-body { background: var(--bg2) !important; }

/* =========================================================
   TABS (panel de detalles)
   ========================================================= */
.x-tab-panel-header, ul.x-tab-strip-top, .x-tab-strip-wrap {
  background: var(--bg3) !important;
  background-image: none !important;
  border-color: var(--border) !important;
}
ul.x-tab-strip-top { border-bottom-color: var(--border) !important; }
.x-tab-strip-top .x-tab-right,
.x-tab-strip-top .x-tab-left,
.x-tab-strip-top .x-tab-strip-inner {
  background-image: none !important;
}
.x-tab-strip-top li { border-radius: 4px 4px 0 0; }
.x-tab-strip-top li .x-tab-right { border-radius: 4px 4px 0 0; }
.x-tab-strip-top li.x-tab-strip-over .x-tab-right { background: var(--bg4) !important; }
.x-tab-strip-top li.x-tab-strip-active .x-tab-right {
  background: var(--bg2) !important;
  box-shadow: inset 0 2px 0 var(--accent);
}
.x-tab-strip span.x-tab-strip-text { color: var(--text-dim) !important; }
.x-tab-strip-active span.x-tab-strip-text,
.x-tab-strip-over span.x-tab-strip-text { color: var(--text) !important; }
.x-tab-strip-spacer {
  background: var(--bg2) !important; border-color: var(--border) !important;
}
.x-tab-panel-body, .x-tab-panel-bwrap {
  background: var(--bg2) !important; border-color: var(--border) !important;
}
.x-tab-scroller-left, .x-tab-scroller-right { filter: invert(.8); }

/* Pestana "Status" / "Details" */
.x-deluge-status dt, .x-tab-panel-body dl dt { color: var(--text-dim) !important; }
.x-deluge-status dd, .x-tab-panel-body dl dd { color: var(--text) !important; }

/* =========================================================
   VENTANAS (Preferencias, Add, Login, Connection Manager...)
   ========================================================= */
.x-window {
  border-radius: 6px;
  box-shadow: 0 0 0 1px var(--border2), 0 14px 40px rgba(0,0,0,.6);
}
.x-window-tl, .x-window-tr, .x-window-tc,
.x-window-ml, .x-window-mr, .x-window-mc,
.x-window-bl, .x-window-br, .x-window-bc,
.x-window-plain .x-window-mc {
  background-image: none !important;
  background-color: var(--bg3) !important;
  border-color: var(--border) !important;
}
.x-window-tl { border-radius: 6px 0 0 0; }
.x-window-tr { border-radius: 0 6px 0 0; }
.x-window-bl { border-radius: 0 0 0 6px; }
.x-window-br { border-radius: 0 0 6px 0; }
.x-window-header { color: var(--text) !important; }
.x-window-body, .x-window-plain .x-window-body {
  background: var(--bg2) !important;
  border-color: var(--border) !important;
}
.x-window-proxy { background: var(--sel) !important; border-color: var(--accent) !important; }
.x-window-maximized .x-window-tc { background: var(--bg3) !important; }

/* Mascaras (fondo modal y paneles deshabilitados) */
.ext-el-mask { background: #000 !important; opacity: .55 !important; }
.ext-el-mask-msg {
  background: var(--bg3) !important; background-image: none !important;
  border-color: var(--border2) !important;
}
.ext-el-mask-msg div {
  background: var(--bg2) !important; color: var(--text) !important;
  border-color: var(--border) !important;
}

/* =========================================================
   FORMULARIOS
   ========================================================= */
.x-form-text, .x-form-field, textarea.x-form-field,
input.x-form-text, .x-form-textarea, .x-trigger-wrap-focus .x-form-text {
  background: var(--bg-input) !important;
  background-image: none !important;
  border: 1px solid var(--border2) !important;
  color: var(--text) !important;
  border-radius: 3px;
}
.x-form-focus, .x-form-text:focus, textarea:focus {
  border-color: var(--accent) !important;
  outline: none !important;
  box-shadow: 0 0 0 2px var(--sel);
}
.x-form-empty-field { color: var(--text-dim) !important; }
.x-form-invalid, textarea.x-form-invalid {
  border-color: var(--p-error) !important; background-image: none !important;
}
.x-form-trigger, .x-form-spinner-split, .x-form-spinner-up, .x-form-spinner-down,
.x-form-spinner-splitter, .x-form-twin-triggers .x-form-trigger {
  filter: invert(.88) hue-rotate(180deg);
  border-color: transparent !important;
}
.x-item-disabled .x-form-text, .x-form-field[disabled] { opacity: .5; }

fieldset, .x-fieldset {
  border-color: var(--border) !important;
  background: transparent !important;
  border-radius: 4px;
}
.x-fieldset legend, .x-fieldset-header-text, legend {
  color: var(--accent) !important;
  font-weight: 600;
}

/* Combos desplegables */
.x-combo-list, .x-combo-list-inner, .x-combo-list-hd {
  background: var(--bg3) !important;
  background-image: none !important;
  border-color: var(--border2) !important;
  color: var(--text) !important;
}
.x-combo-list-item { color: var(--text) !important; border-color: transparent !important; }
.x-combo-selected {
  background: var(--sel) !important;
  border: 1px solid var(--sel-bd) !important;
}

/* =========================================================
   MENUS (clic derecho, menus de columna, statusbar)
   ========================================================= */
.x-menu, .x-menu-floating, .x-menu-list {
  background: var(--bg3) !important;
  background-image: none !important;
  border-color: var(--border2) !important;
}
.x-menu { box-shadow: 0 8px 24px rgba(0,0,0,.5); border-radius: 4px; }
.x-menu-item, .x-menu-item-text, a.x-menu-item { color: var(--text) !important; }
.x-menu-item-active, .x-menu-list-item:hover > .x-menu-item {
  background: var(--sel) !important;
  background-image: none !important;
  border-color: var(--sel-bd) !important;
  border-radius: 3px;
}
.x-menu-item-active .x-menu-item-text { color: #fff !important; }
.x-menu-sep { background: var(--border2) !important; border-color: var(--border2) !important; }
.x-menu-item-arrow { filter: invert(.8); }

/* =========================================================
   ARBOLES (pestana Files, dialogo Add)
   ========================================================= */
.x-tree-root-ct, .x-tree-node, .x-treegrid-root-table, .x-treegrid-root-node {
  background: transparent !important;
  color: var(--text) !important;
}
.x-tree-node .x-tree-node-el, .x-tree-node a span, .x-treegrid-col { color: var(--text) !important; }
.x-treegrid-col, .x-treegrid-root-table, .x-treegrid-root-table td { border-color: var(--border) !important; }
.x-tree-node .x-tree-node-over,
.x-treegrid-root-table .x-tree-node-over { background: var(--bg4) !important; }
.x-tree-node .x-tree-selected,
.x-treegrid-root-table .x-tree-selected { background: var(--sel) !important; }
.x-tree-node .x-tree-selected a span { color: #fff !important; }
.x-treegrid-hd-row td, .x-treegrid-header, .x-treegrid-header-inner {
  background: var(--bg3) !important; background-image: none !important;
  border-color: var(--border) !important;
}
.x-tree-ec-icon, .x-tree-elbow-plus, .x-tree-elbow-minus,
.x-tree-elbow-end-plus, .x-tree-elbow-end-minus { filter: invert(.7); }

/* =========================================================
   TOOLTIPS
   ========================================================= */
.x-tip .x-tip-tl, .x-tip .x-tip-tr, .x-tip .x-tip-tc,
.x-tip .x-tip-ml, .x-tip .x-tip-mr, .x-tip .x-tip-mc,
.x-tip .x-tip-bl, .x-tip .x-tip-br, .x-tip .x-tip-bc {
  background-image: none !important;
  background-color: var(--bg4) !important;
}
.x-tip { border: 1px solid var(--border2); border-radius: 4px; }
.x-tip .x-tip-body, .x-tip-header-text { color: var(--text) !important; }
.x-tip-anchor { display: none !important; }

/* Sombras de ExtJS (sprites claros) */
.x-shadow { opacity: .35; }

/* Barra de progreso en dialogos (MessageBox) */
.ext-mb-progress-wrap .x-progress-bar { background: var(--accent) !important; }
